<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue';import {apiWithVersion} from '../api';
type Item=Record<string,any>;const props=defineProps<{sourceId:string;refreshSignal?:number}>(),emit=defineEmits<{revised:[id:string]}>();
const context=ref<Item|null>(null),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),title=ref(''),text=ref(''),reason=ref(''),version=ref('');
const segments=computed(()=>text.value.split('\n').map(t=>t.trim()).filter(Boolean));
async function load(){const r=await apiWithVersion(`/content/sources/${props.sourceId}/review`);context.value=r.data;version.value=r.version;}
onMounted(async()=>{try{await load()}catch(e){error.value=(e as Error).message}});
watch(()=>props.refreshSignal,async()=>{if(editing.value||busy.value){error.value='原图已变化，请先保留修改，再重新读取来源并核对。';return;}try{await load()}catch(e){error.value=(e as Error).message}});
function edit(){if(!context.value)return;title.value=context.value.source.title+' · 校对版';text.value=context.value.source.text;reason.value='';error.value='';notice.value='';editing.value=true;}
async function save(){if(!context.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{
 const r=await apiWithVersion(`/content/sources/${props.sourceId}/corrections`,{expectedSnapshotHash:context.value.snapshotHash,title:title.value,text:text.value,reason:reason.value},'POST',undefined,version.value);editing.value=false;emit('revised',r.data.id);
}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function confirm(){if(!context.value||busy.value||editing.value)return;busy.value=true;error.value='';notice.value='';try{
 await apiWithVersion(`/content/sources/${props.sourceId}/confirmations`,{expectedSnapshotHash:context.value.snapshotHash,reason:reason.value},'POST',undefined,version.value);await load();reason.value='';notice.value='已记录本来源文字、分段及已关联原图的人工复核。候选生成和发布仍需另行操作。';
}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section class="source-review" aria-label="来源修改与确认"><h3>来源校对与确认</h3><p v-if="!context&&!error" role="status">正在读取复核记录…</p><p v-if="error" role="alert" class="warning">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="context"><p><strong>{{context.confirmed?'已人工复核当前文字与分段':'待人工复核'}}</strong></p><p class="muted">请对照右侧原图。修改时保留原始OCR和旧任务，保存为新的校对版并沿用原图；确认复核另行记录。</p><template v-if="!editing"><button :disabled="busy" @click="edit">修改文字与分段</button><template v-if="!context.confirmed"><label>复核依据<textarea v-model="reason" maxlength="4000" :disabled="busy" placeholder="说明核对了哪些教材页、数学符号、竖式和分段"></textarea></label><button class="primary" :disabled="busy||!reason.trim()" @click="confirm">确认复核通过</button></template><p class="muted">只确认当前来源，不会接受候选、调用模型或发布内容。新关联原图后需要重新核对。</p></template><template v-else><label>校对版标题<input v-model="title" maxlength="500" :disabled="busy"></label><label>校对文字（每行一个分段）<textarea v-model="text" rows="12" maxlength="100000" :disabled="busy"></textarea></label><p class="muted">用换行调整分段。表格条件、竖式和题目上下文请保留完整；关闭面板将放弃未保存修改。</p><details open><summary>保存后的分段预览 · {{segments.length}} 段</summary><article v-for="(segment,i) in segments" :key="i"><strong>段落 {{i+1}}</strong><p>{{segment}}</p></article></details><label>校对说明<textarea v-model="reason" maxlength="4000" :disabled="busy" placeholder="例如：对照书内第13页，把识别错误的减号改为除号；按完整题目调整分段"></textarea></label><button class="primary" :disabled="busy||!reason.trim()||text===context.source.text||text.length<5||!segments.length||!title.trim()" @click="save">保存校对版</button><button :disabled="busy" @click="editing=false;error='';reason=''">取消修改</button><p class="muted">保存后自动打开新校对版，请核对后再点“确认复核通过”。旧候选仍引用原来源，需要对新校对版另行生成。</p></template><details v-if="context.history.length"><summary>校对与复核历史 · {{context.history.length}} 条</summary><article v-for="h in context.history" :key="h.id"><strong>{{h.operation==='Confirmation'?'确认复核':'保存校对版'}} · {{new Date(h.createdAt).toLocaleString('zh-CN')}}</strong><p>{{h.reason}}</p><small>{{h.operation==='Revision'?'原来源 '+h.originalSourceId+' → 校对版 '+h.sourceId:'复核来源 '+h.sourceId}}</small></article></details></template></section></template>
<style scoped>.source-review{padding:16px;background:#eef5ec;border:1px solid #ccdcca;border-radius:10px;margin-bottom:20px}.source-review h3{margin-top:0}.source-review article{border-top:1px solid #ccdcca;padding:10px 0}.source-review p{white-space:pre-wrap;overflow-wrap:anywhere}.source-review small{overflow-wrap:anywhere}.source-review button{margin:4px}.source-review textarea,.source-review input{box-sizing:border-box;width:100%;min-width:0}.source-review details{margin:14px 0}</style>
